//! Golden tests for pgfuncs::bytea against PostgreSQL 17 output
//! (generated by tests/gen/gen_bytea.py).

use pgfuncs::bytea;
use serde_json::Value;

fn load(name: &str) -> Vec<Value> {
    let path = format!("{}/tests/data/{}", env!("CARGO_MANIFEST_DIR"), name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("reading {path}: {e}"));
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| serde_json::from_str(l).unwrap_or_else(|e| panic!("bad json line {l}: {e}")))
        .collect()
}

/// Compare a result against the golden record (either "result" or "error").
fn check(rec: &Value, got: Result<String, pgfuncs::Error>, failures: &mut Vec<String>) {
    let label = format!("{} {}", rec["fn"], rec["args"]);
    match (rec.get("error"), got) {
        (Some(want), Err(e)) => {
            let sqlstate = want["sqlstate"].as_str().unwrap();
            let message = want["message"].as_str().unwrap();
            let detail = want["detail"].as_str();
            if e.sqlstate != sqlstate || e.message != message || e.detail.as_deref() != detail {
                failures.push(format!(
                    "{label}: error got ({}, {:?}, {:?}) want ({sqlstate}, {message:?}, {detail:?})",
                    e.sqlstate, e.message, e.detail
                ));
            }
        }
        (Some(want), Ok(v)) => failures.push(format!("{label}: expected error {want}, got {v:?}")),
        (None, Err(e)) => failures.push(format!("{label}: unexpected error {e:?}, want {}", rec["result"])),
        (None, Ok(v)) => {
            let want = rec["result"].as_str().unwrap();
            if v != want {
                failures.push(format!("{label}: got {v:?} want {want:?}"));
            }
        }
    }
}

#[test]
fn bytea_golden() {
    let mut failures = Vec::new();
    let recs = load("bytea_golden.jsonl");
    for rec in &recs {
        let args = rec["args"].as_array().unwrap();
        let a0 = args[0].as_str().unwrap();
        let got = match rec["fn"].as_str().unwrap() {
            "bytea_in" => bytea::parse(a0).map(|b| bytea::format(&b)),
            "bytea_out_escape" => bytea::parse(a0).map(|b| bytea::format_escape(&b)),
            "encode" => bytea::parse(a0).and_then(|b| bytea::encode(&b, args[1].as_str().unwrap())),
            "decode" => bytea::decode(a0, args[1].as_str().unwrap()).map(|b| bytea::format(&b)),
            other => panic!("unknown fn {other}"),
        };
        check(rec, got, &mut failures);
    }
    assert!(recs.len() > 1000, "too few golden cases: {}", recs.len());
    if !failures.is_empty() {
        panic!("{} of {} golden cases failed:\n{}", failures.len(), recs.len(), failures.join("\n"));
    }
}
